=<?php
// ====== DEBUG SETTINGS ======
error_reporting(E_ALL);
ini_set('display_errors', 1);

echo "🔍 Starting complete WordPress setup script...<br>";

// ====== CONFIGURATION ======
$username     = '{{ $json.username }}';
$sqlUser      = '{{ $json.sqlUser }}';
$sqlPass      = '{{ $json.sqlPass }}';
$dbName       = '{{ $json.username }}_website';
$siteEmail    = '{{ $json.siteEmail }}';
$newPassword  = '{{ $json.newPassword }}';
$newEmail     = '{{ $json.siteEmail }}';
$domain       = '{{ $json.domain }}';
$rootDirectoryPath = '{{ $json["Root directory"] }}';

$wpConfigPath = "/home/$username/public_html/tmp/wp-config.php";
$zipFilePath  = "/home/$username/public_html/{{ $json.zipFileName }}";
$sourceDir    = "/home/$username/public_html/tmp/";
$targetDir    = "/home/$username/{{ $json['Root directory'] }}/";

echo "✅ Configuration loaded<br>";

// ====== CONNECT TO DATABASE ======
try {
    $mysqli = new mysqli('localhost', $username . '_' . $sqlUser, $sqlPass, $dbName);
    if ($mysqli->connect_errno) {
        die("❌ DB connect failed: " . $mysqli->connect_error);
    }
    echo "✅ Connected to database.<br>";
} catch (Exception $e) {
    die("❌ Database exception: " . $e->getMessage());
}

// ====== DEBUG PATHS ======
echo "📍 <strong>Path Configuration:</strong><br>";
echo "Username: $username<br>";
echo "Root Directory Path: '$rootDirectoryPath'<br>";
echo "Source Dir: $sourceDir<br>";
echo "Target Dir: $targetDir<br>";
echo "WP Config Path: $wpConfigPath<br><br>";

// ====== UPDATE wp-config.php ======
echo "📝 <strong>Updating wp-config.php...</strong><br>";
if (file_exists($wpConfigPath)) {
    $config = file_get_contents($wpConfigPath);
    if ($config !== false) {
        $config = preg_replace("/define\\( *'DB_NAME'.*?\\);/", "define('DB_NAME', '$dbName');", $config);
        $config = preg_replace("/define\\( *'DB_USER'.*?\\);/", "define('DB_USER', '{$username}_{$sqlUser}');", $config);
        $config = preg_replace("/define\\( *'DB_PASSWORD'.*?\\);/", "define('DB_PASSWORD', '$sqlPass');", $config);

        if (file_put_contents($wpConfigPath, $config)) {
            echo "✅ wp-config.php updated.<br>";
        } else {
            echo "❌ Failed to write wp-config.php. Check permissions.<br>";
        }
    } else {
        echo "❌ Could not read wp-config.php.<br>";
    }
} else {
    echo "⚠️ wp-config.php not found at: $wpConfigPath<br>";
}

// ====== CHECK DIRECTORIES BEFORE MOVE ======
echo "<br>📂 <strong>Checking directories before move:</strong><br>";
echo "Source exists: " . (is_dir($sourceDir) ? 'YES' : 'NO') . "<br>";
echo "Target exists: " . (is_dir($targetDir) ? 'YES' : 'NO') . "<br>";

// Create target directory if it doesn't exist
if (!is_dir($targetDir)) {
    echo "Creating target directory...<br>";
    if (mkdir($targetDir, 0755, true)) {
        echo "✅ Target directory created.<br>";
    } else {
        echo "❌ Failed to create target directory: " . error_get_last()['message'] . "<br>";
    }
}

// ====== MOVE FILES ======
echo "<br>📦 <strong>Moving files...</strong><br>";
if (is_dir($sourceDir)) {
    $items = scandir($sourceDir);
    if ($items !== false) {
        $moveCount = 0;
        $failCount = 0;

        echo "Found " . (count($items) - 2) . " items to move.<br>";

        foreach ($items as $item) {
            if ($item === '.' || $item === '..') continue;

            $src = $sourceDir . $item;
            $dst = $targetDir . $item;

            echo "Moving: $item... ";

            if (rename($src, $dst)) {
                echo "✅<br>";
                $moveCount++;
            } else {
                echo "❌ Error: " . error_get_last()['message'] . "<br>";
                $failCount++;
            }
        }

        echo "Moved: $moveCount items, Failed: $failCount items<br>";

        if (rmdir($sourceDir)) {
            echo "✅ Source directory removed.<br>";
        } else {
            echo "⚠️ Could not remove source directory.<br>";
        }
    } else {
        echo "❌ Could not scan source directory.<br>";
    }
} else {
    echo "⚠️ Source directory not found at: $sourceDir<br>";
}

// ====== VERIFY FILES AFTER MOVE ======
echo "<br>📋 <strong>Verifying target directory contents:</strong><br>";
if (is_dir($targetDir)) {
    $targetItems = scandir($targetDir);
    echo "Target directory contains " . (count($targetItems) - 2) . " items.<br>";

    // Check for WordPress files
    $wpFiles = ['wp-config.php', 'wp-content', 'wp-admin', 'wp-includes'];
    foreach ($wpFiles as $wpFile) {
        $exists = file_exists($targetDir . '/' . $wpFile);
        echo "$wpFile: " . ($exists ? '✅ Found' : '❌ Not found') . "<br>";
    }
}

// ====== CREATE DIRECTORIES ======
$wpRoot = rtrim($targetDir, '/');
$muDir = $wpRoot . '/wp-content/mu-plugins';
$opsDir = $wpRoot . '/ops';
$tmpImportsDir = $wpRoot . '/tmp_imports';

echo "<br>🔧 <strong>Creating directories...</strong><br>";
echo "WP Root: $wpRoot<br>";
echo "MU Dir: $muDir<br>";
echo "Ops Dir: $opsDir<br>";
echo "Tmp Imports Dir: $tmpImportsDir<br><br>";

// Create mu-plugins directory
if (!is_dir($muDir)) {
    $wpContentDir = dirname($muDir);
    if (!is_dir($wpContentDir)) {
        echo "❌ wp-content directory doesn't exist at: $wpContentDir<br>";
    } else {
        if (mkdir($muDir, 0755, true)) {
            echo "✅ Created mu-plugins directory<br>";
        } else {
            echo "❌ Failed to create mu-plugins: " . error_get_last()['message'] . "<br>";
        }
    }
} else {
    echo "ℹ️ mu-plugins directory already exists<br>";
}

// Create ops directory  
if (!is_dir($opsDir)) {
    if (mkdir($opsDir, 0755, true)) {
        echo "✅ Created ops directory<br>";
    } else {
        echo "❌ Failed to create ops: " . error_get_last()['message'] . "<br>";
    }
} else {
    echo "ℹ️ ops directory already exists<br>";
}

// Create tmp_imports directory
if (!is_dir($tmpImportsDir)) {
    if (mkdir($tmpImportsDir, 0755, true)) {
        echo "✅ Created tmp_imports directory<br>";
    } else {
        echo "❌ Failed to create tmp_imports: " . error_get_last()['message'] . "<br>";
    }
} else {
    echo "ℹ️ tmp_imports directory already exists<br>";
}

echo "<br>✅ Directory creation process completed.<br>";
// ====== CREATE MU PLUGINS (UPDATED VERSIONS) ======
echo "🧠 Creating MU plugins...<br>";

// MU Plugin #1: Elementor cache endpoint (base64 stored safely)
$muFile1 = $muDir . '/elementor-cache-endpoint.php';
$elementorB64 = '';

$elementorCode = base64_decode($elementorB64, true);
if ($elementorCode !== false) {
    @file_put_contents($muFile1, $elementorCode);
    @chmod($muFile1, 0644);
    echo "✅ Elementor MU plugin created.<br>";
}

// MU Plugin #2: Site Updater API Safe (NEW VERSION)
$muFile2 = $muDir . '/site-updater-endpoint.php';
$siteUpdaterCode = <<<'PLUGIN2'
<?php
/**
 * Plugin Name: Site Updater API Safe (MU) - FIXED
 * Description: Safe API that updates content without auto-publishing to avoid Elementor conflicts - FIXED URL handling
 * Version: 4.3.0
 */

if ( ! defined('ABSPATH') ) { return; }

add_action('rest_api_init', function () {
    register_rest_route('site-updater/v2', '/update', [
        'methods'             => 'POST',
        'callback'            => 'su_safe_content_update_handler',
        'permission_callback' => 'su_safe_permission_check',
    ]);

    register_rest_route('site-updater/v2', '/publish', [
        'methods'             => 'POST',
        'callback'            => 'su_manual_publish_handler',
        'permission_callback' => 'su_safe_permission_check',
    ]);

    register_rest_route('site-updater/v2', '/content', [
        'methods'             => 'GET',
        'callback'            => 'su_get_content_handler',
        'permission_callback' => 'su_safe_permission_check',
    ]);

    register_rest_route('site-updater/v2', '/test', [
        'methods'             => 'GET',
        'callback'            => 'su_test_handler',
        'permission_callback' => 'su_safe_permission_check',
    ]);

    // NEW: Debug endpoint to check stored values
    register_rest_route('site-updater/v2', '/debug', [
        'methods'             => 'GET',
        'callback'            => 'su_debug_handler',
        'permission_callback' => 'su_safe_permission_check',
    ]);
});

function su_safe_permission_check() {
    if (current_user_can('manage_options')) {
        return true;
    }

    $auth_header = '';
    if (isset($_SERVER['HTTP_AUTHORIZATION'])) {
        $auth_header = $_SERVER['HTTP_AUTHORIZATION'];
    } elseif (function_exists('getallheaders')) {
        $headers = getallheaders();
        $auth_header = isset($headers['Authorization']) ? $headers['Authorization'] : '';
    }

    if (strpos($auth_header, 'Basic ') === 0) {
        return current_user_can('manage_options');
    }

    return new WP_Error('unauthorized', 'Authentication required', ['status' => 401]);
}

function su_test_handler( WP_REST_Request $req ) {
    return new WP_REST_Response([
        'status' => 'success',
        'message' => 'API authentication working',
        'timestamp' => current_time('mysql'),
        'user' => wp_get_current_user()->user_login ?? 'anonymous'
    ], 200);
}

// NEW: Debug handler to check what's stored
function su_debug_handler( WP_REST_Request $req ) {
    global $wpdb;

    $section = $req->get_param('section') ?? 'header';
    $key = $req->get_param('key') ?? 'image1';

    $option_name = "dyn_{$section}_{$key}";
    $value = get_option($option_name, 'NOT_FOUND');

    // Get all dyn_ options for debugging
    $results = $wpdb->get_results(
        "SELECT option_name, option_value FROM {$wpdb->options} WHERE option_name LIKE 'dyn_%' ORDER BY option_name",
        ARRAY_A
    );

    $attachment_id = 0;
    if ($value !== 'NOT_FOUND' && filter_var($value, FILTER_VALIDATE_URL)) {
        $attachment_id = attachment_url_to_postid($value);
    }

    return new WP_REST_Response([
        'debug_info' => [
            'requested_option' => $option_name,
            'stored_value' => $value,
            'value_length' => strlen($value),
            'is_url' => filter_var($value, FILTER_VALIDATE_URL) !== false,
            'attachment_id' => $attachment_id,
            'timestamp' => current_time('mysql')
        ],
        'all_dyn_options' => $results
    ]);
}

/**
 * FIXED Safe Content Update - Better URL handling
 */
function su_safe_content_update_handler( WP_REST_Request $req ) {
    try {
        $payload = $req->get_json_params();

        if (!is_array($payload)) {
            return new WP_REST_Response(['error' => 'Invalid JSON payload'], 400);
        }

        $results = [
            'status' => 'success',
            'updated_count' => 0,
            'updated_keys' => [],
            'errors' => [],
            'cache_cleared' => false,
            'timestamp' => current_time('mysql'),
            'note' => 'Content updated successfully with FIXED URL handling. Pages remain in current status to avoid Elementor conflicts.'
        ];

        // FIXED: Better content handling with proper URL preservation
        if (!empty($payload['content']) && is_array($payload['content'])) {
            foreach ($payload['content'] as $section => $content) {
                if (!is_array($content)) {
                    $results['errors'][] = "Section '{$section}' must be an object";
                    continue;
                }

                foreach ($content as $key => $value) {
                    try {
                        $option_name = "dyn_" . sanitize_key($section) . "_" . sanitize_key($key);
                        $old_value = get_option($option_name, null);

                        // FIXED: Better value sanitization that preserves URLs
                        $sanitized_value = su_safe_sanitize_value($value);

                        // Simple option update - safe operation
                        $update_result = update_option($option_name, $sanitized_value);

                        $results['updated_keys'][] = [
                            'section' => $section,
                            'key' => $key,
                            'option_name' => $option_name,
                            'old_value' => $old_value,
                            'new_value' => $sanitized_value,
                            'original_value' => $value,
                            'update_success' => $update_result,
                            'is_url' => filter_var($sanitized_value, FILTER_VALIDATE_URL) !== false
                        ];
                        $results['updated_count']++;

                    } catch (Exception $e) {
                        $results['errors'][] = "Failed to update {$option_name}: " . $e->getMessage();
                    }
                }
            }
        }

        // Only clear simple caches - avoid Elementor operations
        $options = $payload['options'] ?? [];
        if ($options['clear_cache'] ?? true) {
            $results['cache_cleared'] = su_safe_simple_cache_clear();
        }

        return new WP_REST_Response($results, 200);

    } catch (Exception $e) {
        return new WP_REST_Response([
            'status' => 'error',
            'message' => 'Server error: ' . $e->getMessage(),
            'timestamp' => current_time('mysql')
        ], 500);
    }
}

/**
 * FIXED: Better value sanitization that preserves URLs properly
 */
function su_safe_sanitize_value($value) {
    // If it looks like a URL, treat it as such
    if (filter_var($value, FILTER_VALIDATE_URL)) {
        return esc_url_raw($value);
    }

    // If it looks like a relative URL path (starts with /)
    if (is_string($value) && (strpos($value, '/wp-content/') === 0 || strpos($value, '/') === 0)) {
        return esc_url_raw($value);
    }

    // If it contains common image extensions, treat as URL
    if (is_string($value) && preg_match('/\.(jpg|jpeg|png|gif|webp|svg)(\?.*)?$/i', $value)) {
        return esc_url_raw($value);
    }

    // If it's numeric, keep as is
    if (is_numeric($value)) {
        return $value;
    }

    // For everything else, use basic sanitization
    return sanitize_text_field($value);
}

/**
 * Manual publish endpoint - separate from content updates (unchanged)
 */
function su_manual_publish_handler( WP_REST_Request $req ) {
    try {
        $payload = $req->get_json_params();
        $options = $payload['options'] ?? [];
        $post_ids = $payload['post_ids'] ?? []; // NEW: Accept specific post IDs

        $results = [
            'status' => 'success',
            'published_pages' => [],
            'timestamp' => current_time('mysql')
        ];

        // NEW: If specific post IDs provided, use those. Otherwise, get all draft/private
        if (!empty($post_ids) && is_array($post_ids)) {
            // Publish specific posts
            $page_ids = array_map('intval', $post_ids);
            $page_ids = array_filter($page_ids, function($id) { return $id > 0; });
        } else {
            // Original behavior - get all draft/private posts
            $page_ids = get_posts([
                'post_type' => ['page', 'post'],
                'post_status' => ['draft', 'private'],
                'posts_per_page' => -1,
                'fields' => 'ids',
                'suppress_filters' => true
            ]);
        }

        foreach ($page_ids as $page_id) {
            // NEW: For specific IDs, check if post exists and can be published
            if (!empty($post_ids)) {
                $post = get_post($page_id);
                if (!$post || !in_array($post->post_status, ['draft', 'private', 'publish'])) {
                    continue; // Skip if post doesn't exist or has invalid status
                }
            }

            $updated = wp_update_post([
                'ID' => $page_id,
                'post_status' => 'publish'
            ], true);

            if (!is_wp_error($updated)) {
                $page = get_post($page_id);
                $results['published_pages'][] = [
                    'page_id' => $page_id,
                    'title' => $page->post_title,
                    'url' => get_permalink($page_id)
                ];
            }
        }

        return new WP_REST_Response($results, 200);

    } catch (Exception $e) {
        return new WP_REST_Response([
            'status' => 'error',
            'message' => 'Publish error: ' . $e->getMessage()
        ], 500);
    }
}

function su_get_content_handler( WP_REST_Request $req ) {
    global $wpdb;

    $results = $wpdb->get_results(
        "SELECT option_name, option_value FROM {$wpdb->options} WHERE option_name LIKE 'dyn_%'",
        ARRAY_A
    );

    $content = [];
    foreach ($results as $result) {
        $option_name = $result['option_name'];
        $parts = explode('_', $option_name, 3);

        if (count($parts) >= 3) {
            $section = $parts[1];
            $key = $parts[2];

            if (!isset($content[$section])) {
                $content[$section] = [];
            }
            $content[$section][$key] = $result['option_value'];
        }
    }

    return new WP_REST_Response([
        'content' => $content,
        'timestamp' => current_time('mysql'),
        'site_url' => get_site_url()
    ]);
}

/**
 * Simple cache clearing - avoid Elementor operations (unchanged)
 */
function su_safe_simple_cache_clear() {
    $cleared = [];

    try {
        // Basic WordPress cache
        if (function_exists('wp_cache_flush')) {
            wp_cache_flush();
            $cleared[] = 'WordPress Cache';
        }

        // Plugin caches (but not Elementor)
        if (function_exists('w3tc_flush_all')) {
            w3tc_flush_all();
            $cleared[] = 'W3 Total Cache';
        }

        if (function_exists('wp_cache_clear_cache')) {
            wp_cache_clear_cache();
            $cleared[] = 'WP Super Cache';
        }

        if (function_exists('rocket_clean_domain')) {
            rocket_clean_domain();
            $cleared[] = 'WP Rocket';
        }

    } catch (Exception $e) {
        // Continue on error
    }

    return $cleared;
}
PLUGIN2;

@file_put_contents($muFile2, $siteUpdaterCode);
@chmod($muFile2, 0644);
echo "✅ Site Updater API Safe MU plugin created.<br>";

// MU Plugin #3: SU Dynamic Tags (NEW)
$muFile3 = $muDir . '/su-dynamic-tags.php';
$dynamicTagsCode = <<<'PLUGIN3'
<?php
/**
 * Plugin Name: SU Dynamic Tags Complete with Working Image Sizing (MU)
 * Description: All dynamic tags including working counter and WORKING image handling with sizing controls
 * Version: 4.0.0
 */

if ( ! defined('ABSPATH') ) { exit; }

add_action('elementor/dynamic_tags/register', function($dynamic_tags) {

    // Text Content Tag
    if (!class_exists('SU_Clean_Text_Tag')) {
        class SU_Clean_Text_Tag extends \Elementor\Core\DynamicTags\Tag {

            public function get_name() { return 'su_clean_text'; }
            public function get_title() { return 'SU Text Content'; }
            public function get_group() { return 'site'; }
            public function get_categories() { return [\Elementor\Modules\DynamicTags\Module::TEXT_CATEGORY]; }

            protected function register_controls() {
                $this->add_control('clean_text_section', [
                    'label' => 'Section',
                    'type' => \Elementor\Controls_Manager::SELECT,
                    'options' => [
                        'hero' => 'Hero',
                        'header' => 'Header',
                        'about' => 'About',
                        'services' => 'Services',
                        'contact' => 'Contact',
                        'company' => 'Company',
                        'footer' => 'Footer',
                    ],
                    'default' => 'hero',
                ]);

                $this->add_control('clean_text_key', [
                    'label' => 'Content Key',
                    'type' => \Elementor\Controls_Manager::TEXT,
                    'placeholder' => 'title, subtitle, phone, email...',
                ]);

                $this->add_control('clean_text_fallback', [
                    'label' => 'Fallback Text',
                    'type' => \Elementor\Controls_Manager::TEXTAREA,
                ]);
            }

            public function render() {
                $settings = $this->get_settings();
                $section = $settings['clean_text_section'] ?? 'hero';
                $key = trim($settings['clean_text_key'] ?? '');
                $fallback = $settings['clean_text_fallback'] ?? '';

                if (empty($key)) {
                    echo esc_html($fallback);
                    return;
                }

                $option_name = "dyn_{$section}_{$key}";
                $value = get_option($option_name, $fallback);
                echo esc_html($value);
            }
        }
    }

    // URL Tag
    if (!class_exists('SU_Clean_URL_Tag')) {
        class SU_Clean_URL_Tag extends \Elementor\Core\DynamicTags\Tag {

            public function get_name() { return 'su_clean_url'; }
            public function get_title() { return 'SU URL Content'; }
            public function get_group() { return 'site'; }
            public function get_categories() { return [\Elementor\Modules\DynamicTags\Module::URL_CATEGORY]; }

            protected function register_controls() {
                $this->add_control('clean_url_section', [
                    'label' => 'Section',
                    'type' => \Elementor\Controls_Manager::SELECT,
                    'options' => [
                        'hero' => 'Hero',
                        'header' => 'Header', 
                        'social' => 'Social',
                        'contact' => 'Contact',
                    ],
                    'default' => 'hero',
                ]);

                $this->add_control('clean_url_key', [
                    'label' => 'URL Key',
                    'type' => \Elementor\Controls_Manager::TEXT,
                    'placeholder' => 'button_url, facebook_url, logo_url...',
                ]);

                $this->add_control('clean_url_fallback', [
                    'label' => 'Fallback URL',
                    'type' => \Elementor\Controls_Manager::TEXT,
                    'default' => '#',
                ]);
            }

            public function render() {
                $settings = $this->get_settings();
                $section = $settings['clean_url_section'] ?? 'hero';
                $key = trim($settings['clean_url_key'] ?? '');
                $fallback = $settings['clean_url_fallback'] ?? '#';

                if (empty($key)) {
                    echo esc_url($fallback);
                    return;
                }

                $option_name = "dyn_{$section}_{$key}";
                $value = get_option($option_name, $fallback);
                echo esc_url($value);
            }
        }
    }

    // Working Data Tag - Clean Implementation with Image Sizing
    if (!class_exists('SU_Working_Data_Tag')) {
        class SU_Working_Data_Tag extends \Elementor\Core\DynamicTags\Data_Tag {

            public function get_name() { return 'su_working_data'; }
            public function get_title() { return 'SU Working Data Tag'; }
            public function get_group() { return 'media'; }
            public function get_categories() { 
                return [\Elementor\Modules\DynamicTags\Module::IMAGE_CATEGORY]; 
            }

            protected function register_controls() {
                $this->add_control('section', [
                    'label' => 'Section',
                    'type' => \Elementor\Controls_Manager::SELECT,
                    'options' => [
                        'header' => 'Header',
                        'hero' => 'Hero',
                        'services' => 'Services',
                        'about' => 'About',
                    ],
                    'default' => 'header',
                ]);

                $this->add_control('key', [
                    'label' => 'Image Key',
                    'type' => \Elementor\Controls_Manager::TEXT,
                    'default' => 'image1',
                ]);

                // Add fallback for better reliability
                $this->add_control('fallback_image', [
                    'label' => 'Fallback Image',
                    'type' => \Elementor\Controls_Manager::MEDIA,
                    'dynamic' => [
                        'active' => true,
                        'categories' => [
                            \Elementor\Modules\DynamicTags\Module::IMAGE_CATEGORY,
                        ],
                    ],
                ]);
            }

            public function get_value(array $options = []) {
                $settings = $this->get_settings();
                $section = $settings['section'] ?? 'header';
                $key = trim($settings['key'] ?? 'image1');

                $option_name = "dyn_{$section}_{$key}";
                $url = get_option($option_name, '');
                $attachment_id = 0;

                if (!empty($url)) {
                    $attachment_id = attachment_url_to_postid($url);
                }

                // Handle fallback
                if (empty($attachment_id)) {
                    $fallback = $settings['fallback_image'] ?? [];
                    if (!empty($fallback['id'])) {
                        $attachment_id = $fallback['id'];
                    }
                }

                if ($attachment_id && wp_attachment_is_image($attachment_id)) {
                    return [
                        'id' => $attachment_id,
                        'url' => wp_get_attachment_image_url($attachment_id, 'full'),
                        'alt' => get_post_meta($attachment_id, '_wp_attachment_image_alt', true),
                    ];
                }

                return false;
            }
        }
    }

    // Counter Number Tag
    if (!class_exists('SU_Clean_Counter_Tag')) {
        class SU_Clean_Counter_Tag extends \Elementor\Core\DynamicTags\Tag {

            public function get_name() { return 'su_clean_counter'; }
            public function get_title() { return 'SU Counter Number'; }
            public function get_group() { return 'site'; }
