            protected function register_controls() {
                $this->add_control('clean_counter_section', [
                    'label' => 'Section',
                    'type' => \Elementor\Controls_Manager::SELECT,
                    'options' => [
                        'hero' => 'Hero',
                        'stats' => 'Statistics',
                        'about' => 'About',
                        'services' => 'Services',
                        'company' => 'Company',
                    ],
                    'default' => 'hero',
                ]);

                $this->add_control('clean_counter_key', [
                    'label' => 'Counter Key',
                    'type' => \Elementor\Controls_Manager::TEXT,
                    'placeholder' => 'years_experience, clients_served, projects_completed...',
                ]);

                $this->add_control('clean_counter_fallback', [
                    'label' => 'Fallback Number',
                    'type' => \Elementor\Controls_Manager::NUMBER,
                    'default' => 0,
                ]);

                $this->add_control('clean_counter_format', [
                    'label' => 'Number Format',
                    'type' => \Elementor\Controls_Manager::SELECT,
                    'options' => [
                        'none' => 'No formatting (1234)',
                        'comma' => 'Comma separated (1,234)',
                        'plus' => 'Add plus sign (1,234+)',
                        'percent' => 'Add percent (1,234%)',
                    ],
                    'default' => 'comma',
                ]);
            }

            public function render() {
                $settings = $this->get_settings();
                $section = $settings['clean_counter_section'] ?? 'hero';
                $key = trim($settings['clean_counter_key'] ?? '');
                $fallback = intval($settings['clean_counter_fallback'] ?? 0);
                $format = $settings['clean_counter_format'] ?? 'comma';

                if (empty($key)) {
                    echo $this->format_number($fallback, $format);
                    return;
                }

                $option_name = "dyn_{$section}_{$key}";
                $value = get_option($option_name, $fallback);

                // Ensure it's a number
                $number = intval($value);
                echo $this->format_number($number, $format);
            }

            private function format_number($number, $format) {
                switch ($format) {
                    case 'comma':
                        return number_format($number);
                    case 'plus':
                        return number_format($number) . '+';
                    case 'percent':
                        return number_format($number) . '%';
                    case 'none':
                    default:
                        return $number;
                }
            }
        }
