// JavaScript solution for dynamic sizing control
add_action('wp_footer', function() {
    if (is_admin()) return; // Don't run in admin

    echo '<script>
        document.addEventListener("DOMContentLoaded", function() {
            // Function to apply image sizing
            function applySUImageSizing() {
                // Find all images in Elementor widgets
                const imageWidgets = document.querySelectorAll(".elementor-widget-image, .elementor-widget-image-box");

                imageWidgets.forEach(function(widget) {
                    const img = widget.querySelector("img");
                    if (!img) return;

                    // Check if this widget has SU dynamic content (you can identify by checking URL pattern)
                    const imgSrc = img.src;
                    if (imgSrc && imgSrc.includes("wp-content/uploads")) {
                        // Apply default sizing for dynamic images
                        img.style.width = "100%";
                        img.style.height = "300px";
                        img.style.objectFit = "cover";
                        img.style.objectPosition = "center";

                        // Add class for easier targeting
                        widget.classList.add("su-dynamic-sized");
                    }
                });
            }

            // Apply sizing immediately
            applySUImageSizing();

            // Reapply after images load
            setTimeout(applySUImageSizing, 1000);
        });

        // Expose function globally for manual control
        window.setSUImageSize = function(selector, height, fit) {
            const elements = document.querySelectorAll(selector + " img");
            elements.forEach(function(img) {
                img.style.width = "100%";
                img.style.height = height + "px";
                img.style.objectFit = fit || "cover";
                img.style.objectPosition = "center";
            });
        };
    </script>';
});
