$backupApiCode = <<<'PLUGIN4'
<?php
/**
 * Plugin Name: SU Backup & Document Management API (MU)
 * Description: Complete backup system and document management for Elementor sites
 * Version: 1.0.0
 */

if ( ! defined('ABSPATH') ) { return; }

add_action('rest_api_init', function () {
	// Original dynamic values endpoint
	register_rest_route('su/v1', '/dynamic-values', [
		'methods'  => 'GET',
		'callback' => function () {
			global $wpdb;
			$options = $wpdb->get_results("SELECT option_name, option_value FROM {$wpdb->options} WHERE option_name LIKE 'dyn_%' AND option_value IS NOT NULL AND option_value != ''");
			$out = [];
			foreach ($options as $o) {
				$v = maybe_unserialize($o->option_value);
				$out[$o->option_name] = is_string($v) ? wp_unslash($v) : $v;
			}
			return new WP_REST_Response(['success'=>true,'values'=>$out], 200);
		},
		'permission_callback' => function(){ return current_user_can('manage_options'); },
	]);

	// Original doc export endpoint
	register_rest_route('su/v1', '/doc-export', [
		'methods'  => 'GET',
		'args'     => ['id' => ['type'=>'integer','required'=>true]],
		'callback' => function ($req) {
			$id = (int) $req->get_param('id');
			$elements = [];
			$settings = [];
			if (class_exists('\Elementor\Plugin')) {
				$doc = \Elementor\Plugin::$instance->documents->get($id);
				if ($doc) {
					$elements = method_exists($doc,'get_elements_raw_data') ? $doc->get_elements_raw_data(true) : (method_exists($doc,'get_elements_data') ? $doc->get_elements_data() : []);
					$settings = method_exists($doc,'get_settings') ? (array) $doc->get_settings() : [];
				}
			}
			if (!$elements) {
				$raw = get_post_meta($id, '_elementor_data', true);
				$elements = json_decode(wp_unslash($raw), true) ?: [];
			}
			if (!$settings) {
				$raw = get_post_meta($id, '_elementor_page_settings', true);
				$settings = json_decode(wp_unslash($raw), true) ?: [];
			}
			return new WP_REST_Response(['success'=>true,'post_id'=>$id,'elements'=>$elements,'settings'=>$settings], 200);
		},
		'permission_callback' => function(){ return current_user_can('manage_options'); },
	]);

	// Original doc import endpoint
	register_rest_route('su/v1', '/doc-import', [
		'methods'  => 'POST',
		'args'     => [
			'post_id'  => ['type'=>'integer','required'=>true],
			'elements' => ['required'=>true],
			'settings' => ['required'=>false],
		],
		'callback' => function ($req) {
			$id = (int) $req->get_param('post_id');
			$elements = $req->get_param('elements');
			$settings = $req->get_param('settings') ?: [];

			if (class_exists('\Elementor\Plugin')) {
				$doc = \Elementor\Plugin::$instance->documents->get($id);
				if ($doc && method_exists($doc,'save')) {
					$doc->save(['elements'=>$elements,'settings'=>$settings]);
					delete_post_meta($id, '_elementor_css');
					if (isset(\Elementor\Plugin::$instance->files_manager) && method_exists(\Elementor\Plugin::$instance->files_manager, 'clear_cache_for_post')) {
						\Elementor\Plugin::$instance->files_manager->clear_cache_for_post($id);
					}
					if (method_exists($doc,'get_css_wrapper')) {
						$css = $doc->get_css_wrapper();
						if ($css && method_exists($css,'update')) $css->update();
					}
					clean_post_cache($id);
					return new WP_REST_Response(['success'=>true], 200);
				}
			}

			// Fallback
			update_post_meta($id, '_elementor_data', wp_slash(wp_json_encode($elements, JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)));
			update_post_meta($id, '_elementor_page_settings', wp_slash(wp_json_encode($settings, JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)));
			delete_post_meta($id, '_elementor_css');
			clean_post_cache($id);
			return new WP_REST_Response(['success'=>true,'fallback'=>true], 200);
		},
		'permission_callback' => function(){ return current_user_can('manage_options'); },
	]);

	// NEW: Create backup endpoint
	register_rest_route('su/v1', '/backup-create', [
		'methods'  => 'POST',
		'args'     => [
			'name' => ['type'=>'string','required'=>true],
			'timestamp' => ['type'=>'string','required'=>true],
			'post_ids' => ['type'=>'array','required'=>true],
			'posts' => ['type'=>'object','required'=>true],
		],
		'callback' => function ($req) {
			$backup_data = [
				'name' => sanitize_text_field($req->get_param('name')),
				'timestamp' => $req->get_param('timestamp'),
				'post_ids' => array_map('intval', $req->get_param('post_ids')),
				'posts' => $req->get_param('posts'),
				'created_by' => get_current_user_id(),
			];

			$option_name = 'su_backup_' . sanitize_key($backup_data['name']);

			if (get_option($option_name, false) !== false) {
				return new WP_REST_Response([
					'success' => false,
					'message' => 'Backup with this name already exists'
				], 409);
			}

			$result = update_option($option_name, $backup_data, false);

			if ($result) {
				return new WP_REST_Response([
					'success' => true,
					'backup_name' => $backup_data['name'],
					'post_count' => count($backup_data['post_ids'])
				], 200);
			} else {
				return new WP_REST_Response([
					'success' => false,
					'message' => 'Failed to save backup'
				], 500);
			}
		},
		'permission_callback' => function(){ return current_user_can('manage_options'); },
	]);

	// NEW: List backups endpoint
	register_rest_route('su/v1', '/backup-list', [
		'methods'  => 'GET',
		'callback' => function () {
			global $wpdb;
			$results = $wpdb->get_results(
				"SELECT option_name, option_value FROM {$wpdb->options} WHERE option_name LIKE 'su_backup_%'"
			);

			$backups = [];
			foreach ($results as $row) {
				$backup = maybe_unserialize($row->option_value);
				if ($backup && is_array($backup)) {
					$backups[] = [
						'name' => $backup['name'],
						'timestamp' => $backup['timestamp'],
						'post_ids' => $backup['post_ids'],
						'post_count' => count($backup['post_ids']),
						'created_by' => $backup['created_by'] ?? 0,
					];
				}
			}

			// Sort by timestamp (newest first)
			usort($backups, function($a, $b) {
				return strcmp($b['timestamp'], $a['timestamp']);
			});

			return new WP_REST_Response([
				'success' => true,
				'backups' => $backups,
				'count' => count($backups)
			], 200);
		},
		'permission_callback' => function(){ return current_user_can('manage_options'); },
	]);

	// NEW: Restore backup endpoint
	register_rest_route('su/v1', '/backup-restore', [
		'methods'  => 'POST',
		'args'     => [
			'backup_name' => ['type'=>'string','required'=>true],
			'post_ids' => ['type'=>'array','required'=>false], // If specified, only restore these posts
		],
		'callback' => function ($req) {
			$backup_name = sanitize_text_field($req->get_param('backup_name'));
			$specific_post_ids = $req->get_param('post_ids');
			$option_name = 'su_backup_' . sanitize_key($backup_name);

			$backup_data = get_option($option_name, false);
			if (!$backup_data || !is_array($backup_data)) {
				return new WP_REST_Response([
					'success' => false,
					'message' => 'Backup not found: ' . $backup_name
				], 404);
			}

			$posts_to_restore = $specific_post_ids ? array_intersect($backup_data['post_ids'], array_map('intval', $specific_post_ids)) : $backup_data['post_ids'];
			$restored_posts = [];
			$errors = [];

			foreach ($posts_to_restore as $post_id) {
				if (!isset($backup_data['posts'][$post_id])) {
					$errors[] = "Post {$post_id} not found in backup";
					continue;
				}

				$post_backup = $backup_data['posts'][$post_id];
				$elements = $post_backup['elements'];
				$settings = $post_backup['settings'];

				try {
					// Try using Elementor API first
					if (class_exists('\Elementor\Plugin')) {
						$doc = \Elementor\Plugin::$instance->documents->get($post_id);
						if ($doc && method_exists($doc,'save')) {
							$doc->save(['elements'=>$elements,'settings'=>$settings]);
							delete_post_meta($post_id, '_elementor_css');
							if (isset(\Elementor\Plugin::$instance->files_manager) && method_exists(\Elementor\Plugin::$instance->files_manager, 'clear_cache_for_post')) {
								\Elementor\Plugin::$instance->files_manager->clear_cache_for_post($post_id);
							}
							if (method_exists($doc,'get_css_wrapper')) {
								$css = $doc->get_css_wrapper();
								if ($css && method_exists($css,'update')) $css->update();
							}
							clean_post_cache($post_id);
							$restored_posts[] = $post_id;
							continue;
						}
					}

					// Fallback to direct meta updates
					update_post_meta($post_id, '_elementor_data', wp_slash(wp_json_encode($elements, JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)));
					update_post_meta($post_id, '_elementor_page_settings', wp_slash(wp_json_encode($settings, JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE)));
					delete_post_meta($post_id, '_elementor_css');
					clean_post_cache($post_id);
					$restored_posts[] = $post_id;

				} catch (Exception $e) {
					$errors[] = "Post {$post_id}: " . $e->getMessage();
				}
			}

			return new WP_REST_Response([
				'success' => true,
				'backup_name' => $backup_name,
				'restored_count' => count($restored_posts),
				'restored_posts' => $restored_posts,
				'errors' => $errors,
				'requested_count' => count($posts_to_restore)
			], 200);
		},
		'permission_callback' => function(){ return current_user_can('manage_options'); },
	]);

	// NEW: Delete backup endpoint
	register_rest_route('su/v1', '/backup-delete', [
		'methods'  => 'POST',
		'args'     => [
			'backup_name' => ['type'=>'string','required'=>true],
		],
		'callback' => function ($req) {
			$backup_name = sanitize_text_field($req->get_param('backup_name'));
			$option_name = 'su_backup_' . sanitize_key($backup_name);

			$backup_data = get_option($option_name, false);
			if (!$backup_data) {
				return new WP_REST_Response([
					'success' => false,
					'message' => 'Backup not found: ' . $backup_name
				], 404);
			}

			$result = delete_option($option_name);

			if ($result) {
				return new WP_REST_Response([
					'success' => true,
					'message' => 'Backup deleted successfully'
				], 200);
			} else {
				return new WP_REST_Response([
					'success' => false,
					'message' => 'Failed to delete backup'
				], 500);
			}
		},
		'permission_callback' => function(){ return current_user_can('manage_options'); },
	]);
});
